def _print_ranked(result: QueryResult, rows: int = 3) -> None:
    print(f"  Question : {result.question}")
    print(f"  Filter   : {result.filter_description}")
    print(f"  Candidates after metadata filter: {result.after_filter} of "
          f"{result.total_chunks} chunks")
    print("  Ranked top results:")
    print("    # | chunk id          | category   | date       | cosine | final | heading")
    print("    --+-------------------+------------+------------+--------+-------+--------")
    for r in result.ranked[:rows]:
        m = r.chunk.metadata
        print(f"    {r.rank:2d} | {r.chunk.chunk_id:17s} | {str(m.get('category','')):10s} | "
              f"{str(m.get('date','')):10s} | {r.cosine:6.3f} | {r.final_score:5.3f} | "
              f"{r.chunk.heading[:38]}")
    print("\n  Answer:")
    for line in result.answer.splitlines():
        print(f"    {line}")
    print()


def _print_cosine_vs_metadata(system: RAGSystem, question: str) -> None:
    pure = system.cosine_ranking(question, top_k=5)
    blended = system.query(question, top_k=5)
    print("  Cosine-only order vs metadata-blended order:")
    print("    rank | cosine-only (chunk / score)              | metadata-blended (chunk / final)")
    print("    -----+------------------------------------------+---------------------------------")
    for i in range(max(len(pure), len(blended.ranked))):
        p = pure[i] if i < len(pure) else None
        b = blended.ranked[i] if i < len(blended.ranked) else None
        p_str = f"{p[0]} / {p[4]:.3f}" if p else "-"
        b_str = f"{b.chunk.chunk_id} / {b.final_score:.3f}" if b else "-"
        print(f"    {i+1:4d} | {p_str:40s} | {b_str}")


def run_single_query(argv: List[str]) -> None:
    def arg_value(flag: str) -> Optional[str]:
        return argv[argv.index(flag) + 1] if flag in argv else None

    question = arg_value("--query")
    if not question:
        print("Usage: --query '...' [--filters '<json>'] [--top-k N]")
        sys.exit(2)
    filters = json.loads(arg_value("--filters") or "{}")
    top_k = int(arg_value("--top-k") or "5")
    system = RAGSystem(ranking_config=make_ranking_config())
    n = system.add_documents(build_corpus())
    print(f"Indexed {n} chunks.\n")
    result = system.query(question, filters or None, top_k)
    _print_ranked(result)


def main() -> None:
    print("=" * 72)
    print(" METADATA-ENHANCED RAG SYSTEM - DEMO")
    print("=" * 72)

    system = RAGSystem(ranking_config=make_ranking_config())
    n = system.add_documents(build_corpus())
    print(f"\n[1] Index build")
    print(f"  Documents indexed : 8")
    print(f"  Chunks created    : {n}")
    print(f"  Vocabulary size   : {len(system.vectorizer.idf)}")
    print(f"  Ranking weights   : {system.config}")

    print(f"\n[2] Demo queries")
    print("-" * 72)

    print("  QUERY A - metadata filter by category (eq)")
    _print_ranked(system.query(
        "What is the reimbursement limit for travel expenses?",
        {"category": "finance"}, top_k=3))

    print("  QUERY B - metadata filter by category (eq) on a security question")
    _print_ranked(system.query(
        "How do I reset my password when locked out?",
        {"category": "security"}, top_k=3))

    print("  QUERY C - no filter: cross-category relevance ranking")
    _print_ranked(system.query(
        "What new features were announced in the Atlas 2.0 launch?", top_k=5))

    print("  QUERY D - metadata filter by date range (gte) + tag filter")
    _print_ranked(system.query(
        "What analytics and automation features does the platform provide?",
        {"date": {"operator": "gte", "value": "2024-10-15"},
         "tags": {"operator": "contains", "value": "features"}}, top_k=4))

    print("  QUERY E - negative test: wrong filter + unrelated content -> fallback")
    _print_ranked(system.query(
        "What is the expense reimbursement limit?", {"category": "hr"}, top_k=3))

    print(f"\n[3] Ranking: relevance vs metadata-enhanced")
    print("-" * 72)
    _print_cosine_vs_metadata(system, "Atlas dashboard analytics automation")

    ok = run_evaluation(system)
    print("\n" + "=" * 72)
    print(" DEMO COMPLETE" if ok else " DEMO COMPLETE (WITH FAILURES)")
    print("=" * 72)
    sys.exit(0 if ok else 1)


if __name__ == "__main__":
    if "--query" in sys.argv:
        run_single_query(sys.argv)
    else:
        main()

#!/usr/bin/env python3
"""
Metadata-Enhanced RAG System
============================
A dependency-free Retrieval-Augmented Generation system that:

  1. Indexes documents as chunks, each carrying rich metadata
     (category, source, date, author, heading, tags, version).
  2. Filters candidates with a structured, operator-based metadata
     predicate engine (eq / ne / in / contains / gt / gte / lt / lte /
     exists / missing) BEFORE similarity search runs.
  3. Ranks candidates with a weighted blend of relevance
     (TF-IDF cosine similarity, query-term overlap) and metadata
     signals (heading match, recency, source authority, category
     priority).
  4. Generates grounded answers with [n] citations from the top chunks,
     and falls back to an explicit "not enough information" response
     when no retrieved chunk is relevant enough.

Usage:
    python rag_metadata_system.py                  # full demo + evaluation
    python rag_metadata_system.py --query "..." \
        --filters '{"category": "finance"}' --top-k 3
"""
from __future__ import annotations

import json
import math
import re
import sys
from dataclasses import dataclass, field
from datetime import datetime
from typing import Any, Dict, Iterable, List, Optional, Sequence, Tuple

# ---------------------------------------------------------------------------
# 1. Text utilities
# ---------------------------------------------------------------------------

STOPWORDS = frozenset(
    "a an and are as at be but by for from has have how i if in into is it its of on or "
    "that the their there these they this to was we what when which who will with you your "
    "do does did can could should would not no than then so just about".split()
)

_TOKEN_RE = re.compile(r"[a-z0-9']+")


def tokenize(text: str) -> List[str]:
    """Lowercase tokenization with stopword removal."""
    return [t for t in _TOKEN_RE.findall(text.lower()) if t not in STOPWORDS]


def term_frequency(tokens: Sequence[str]) -> Dict[str, int]:
    tf: Dict[str, int] = {}
    for tok in tokens:
        tf[tok] = tf.get(tok, 0) + 1
    return tf


def sentence_split(text: str) -> List[str]:
    return [s.strip() for s in re.split(r"(?<=[.!?])\s+", text) if s.strip()]


# ---------------------------------------------------------------------------
# 2. Data model
# ---------------------------------------------------------------------------

@dataclass
class Document:
    """An input document: free text plus a metadata dictionary."""
    text: str
    metadata: Dict[str, Any]


@dataclass
class Chunk:
    """A retrievable unit: text, metadata copy, and a heading for display."""
    chunk_id: str
    text: str
    metadata: Dict[str, Any]
    heading: str = ""

    def __post_init__(self) -> None:
        if not self.heading:
            self.heading = str(self.metadata.get("heading", ""))


@dataclass
class RankedChunk:
    """A chunk with its full ranking score breakdown."""
    chunk: Chunk
    cosine: float
    term_overlap: float
    heading_match: float
    recency: float
    authority: float
    category_priority: float
    final_score: float
    rank: int = 0


@dataclass
class QueryResult:
    question: str
    answer: str
    ranked: List[RankedChunk]
    total_chunks: int
    after_filter: int
    filter_description: str


# ---------------------------------------------------------------------------
# 3. TF-IDF vectorizer (pure Python, no external dependencies)
# ---------------------------------------------------------------------------

class TfidfVectorizer:
    """Small, self-contained TF-IDF vectorizer for dependency-free operation."""

    def __init__(self, sublinear_tf: bool = True):
        self.sublinear_tf = sublinear_tf
        self.idf: Dict[str, float] = {}

    def fit(self, texts: Iterable[str]) -> "TfidfVectorizer":
        n_docs = 0
        df: Dict[str, int] = {}
        for text in texts:
            n_docs += 1
            for term in set(tokenize(text)):
                df[term] = df.get(term, 0) + 1
        for term, doc_count in df.items():
            self.idf[term] = math.log((n_docs + 1) / (doc_count + 1)) + 1.0
        return self

    def transform(self, text: str) -> Dict[str, float]:
        tf = term_frequency(tokenize(text))
        vec: Dict[str, float] = {}
        for term, count in tf.items():
            if term not in self.idf:
                continue
            tf_w = (1.0 + math.log(count)) if self.sublinear_tf and count > 1 else float(count)
            vec[term] = tf_w * self.idf[term]
        return self._unit(vec)

    @staticmethod
    def _unit(vec: Dict[str, float]) -> Dict[str, float]:
        norm = math.sqrt(sum(v * v for v in vec.values()))
        if norm == 0.0:
            return vec
        return {k: v / norm for k, v in vec.items()}

    @staticmethod
    def cosine(a: Dict[str, float], b: Dict[str, float]) -> float:
        if not a or not b:
            return 0.0
        if len(a) > len(b):
            a, b = b, a
        return sum(v * b.get(k, 0.0) for k, v in a.items())


# ---------------------------------------------------------------------------
# 4. Metadata filtering engine
# ---------------------------------------------------------------------------

class MetadataFilterEngine:
    """Structured, operator-based metadata predicates.

    Supported operators:
      eq, ne, in, contains (for list-valued fields),
      gt, gte, lt, lte (numeric or ISO-8601 date strings),
      exists, missing

    Filter spec examples:
      {"category": "finance"}                         -> eq
      {"tags": {"operator": "contains", "value": "mfa"}}
      {"date": {"operator": "gte", "value": "2024-10-01"}}
      {"source": ["product-docs", "marketing"]}       -> in
    """

    @staticmethod
    def _coerce(value: Any) -> Any:
        if isinstance(value, str):
            for fmt in ("%Y-%m-%dT%H:%M:%S", "%Y-%m-%d"):
                try:
                    return datetime.strptime(value, fmt)
                except ValueError:
                    continue
        return value

    @classmethod
    def matches(cls, metadata: Dict[str, Any], field_name: str,
                operator: str, expected: Any) -> bool:
        actual = metadata.get(field_name)
        op = operator.lower()

        if op in ("exists", "missing"):
            return (actual is not None) if op == "exists" else (actual is None)

        if actual is None:
            return False

        if op == "eq":
            return expected in actual if isinstance(actual, list) else actual == expected

        if op == "ne":
            return expected not in actual if isinstance(actual, list) else actual != expected

        if op == "in":
            return actual in list(expected)

        if op == "contains":
            return expected in list(actual)

        if op in ("gt", "gte", "lt", "lte"):
            a, b = cls._coerce(actual), cls._coerce(expected)
            if op == "gt":
                return a > b
            if op == "gte":
                return a >= b
            if op == "lt":
                return a < b
            return a <= b

        raise ValueError(f"Unsupported operator: {operator}")

    @classmethod
    def filter_chunks(cls, chunks: Sequence[Chunk],
                      filters: Optional[Dict[str, Any]]) -> List[Chunk]:
        if not filters:
            return list(chunks)
        out: List[Chunk] = []
        for chunk in chunks:
            ok = True
            for field_name, spec in filters.items():
                if isinstance(spec, dict) and "operator" in spec:
                    operator, expected = spec["operator"], spec.get("value")
                elif isinstance(spec, (list, tuple, set)):
                    operator, expected = "in", spec
                else:
                    operator, expected = "eq", spec
                if not cls.matches(chunk.metadata, field_name, operator, expected):
                    ok = False
                    break
            if ok:
                out.append(chunk)
        return out

    @staticmethod
    def describe(filters: Optional[Dict[str, Any]]) -> str:
        if not filters:
            return "no metadata filter (all chunks eligible)"
        parts = []
        for field_name, spec in filters.items():
            if isinstance(spec, dict) and "operator" in spec:
                parts.append(f"{field_name} {spec['operator']} {spec.get('value')!r}")
            else:
                parts.append(f"{field_name} = {spec!r}")
        return " AND ".join(parts)


# ---------------------------------------------------------------------------
# 5. Chunking
# ---------------------------------------------------------------------------

def chunk_document(doc_index: int, doc: Document, chunk_size: int = 400,
                   overlap: int = 100) -> List[Chunk]:
    """Split a document into overlapping chunks, preserving document metadata."""
    paragraphs = [p.strip() for p in re.split(r"\n\s*\n", doc.text) if p.strip()]
    chunks: List[str] = []
    buffer = ""

    for para in paragraphs:
        if len(buffer) + len(para) <= chunk_size:
            buffer = (buffer + "\n\n" + para).strip()
            continue
        if buffer:
            chunks.append(buffer)
            buffer = ""
        # Split over-long paragraphs on sentence boundaries.
        for sentence in sentence_split(para):
            if len(buffer) + len(sentence) <= chunk_size:
                buffer = (buffer + " " + sentence).strip()
            else:
                if buffer:
                    chunks.append(buffer)
                buffer = sentence
    if buffer:
        chunks.append(buffer)

    # Add overlap between adjacent chunks to preserve boundary context.
    final: List[Chunk] = []
    for i, text in enumerate(chunks):
        if overlap and i > 0:
            tail = chunks[i - 1][-overlap:]
            if tail:
                text = tail.rstrip() + " ... " + text
        meta = dict(doc.metadata)
        meta["chunk_index"] = i
        meta["chunk_count"] = len(chunks)
        final.append(Chunk(
            chunk_id=f"doc{doc_index:03d}-chunk{i:02d}",
            text=text,
            metadata=meta,
            heading=str(doc.metadata.get("heading", "")),
        ))
    return final


# ---------------------------------------------------------------------------
# 6. Ranking
# ---------------------------------------------------------------------------

@dataclass
class RankingConfig:
    """Weights for the final ranking formula (must sum to 1.0).

    final = cosine_weight * cosine_sim
          + overlap_weight  * query_term_overlap
          + heading_weight  * heading_match
          + recency_weight  * normalized_recency
          + authority_weight* source_authority
          + category_weight * category_priority
    """
    cosine_weight: float = 0.72
    overlap_weight: float = 0.12
    heading_weight: float = 0.08
    recency_weight: float = 0.05
    authority_weight: float = 0.02
    category_weight: float = 0.01
    source_authority: Dict[str, float] = field(default_factory=dict)   # source -> 0..1
    category_priority: Dict[str, float] = field(default_factory=dict)  # category -> 0..1


class Ranker:
    """Blends relevance with metadata signals to produce the final ranking."""

    def __init__(self, config: RankingConfig):
        self.config = config
        total = (config.cosine_weight + config.overlap_weight + config.heading_weight
                 + config.recency_weight + config.authority_weight + config.category_weight)
        if abs(total - 1.0) > 1e-6:
            raise ValueError(f"Ranking weights must sum to 1.0, got {total:.4f}")

    @staticmethod
    def _date_of(metadata: Dict[str, Any]) -> Optional[datetime]:
        raw = metadata.get("date")
        if not raw:
            return None
        if isinstance(raw, datetime):
            return raw
        for fmt in ("%Y-%m-%dT%H:%M:%S", "%Y-%m-%d"):
            try:
                return datetime.strptime(str(raw), fmt)
            except ValueError:
                continue
        return None

    def _recency(self, metadata: Dict[str, Any],
                 newest: datetime, oldest: datetime) -> float:
        d = self._date_of(metadata)
        if d is None:
            return 0.5
        span = (newest - oldest).days
        if span <= 0:
            return 1.0
        return max(0.0, min(1.0, (d - oldest).days / span))

    def rank(self, question: str, chunks: Sequence[Chunk],
             cosine_scores: Sequence[float]) -> List[RankedChunk]:
        config = self.config
        query_terms = set(tokenize(question))

        dates = [d for d in (self._date_of(c.metadata) for c in chunks) if d]
        newest = max(dates) if dates else datetime.now()
        oldest = min(dates) if dates else newest

        results: List[RankedChunk] = []
        for chunk, cosine in zip(chunks, cosine_scores):
            meta = chunk.metadata
            chunk_terms = set(tokenize(chunk.text))
            overlap = len(query_terms & chunk_terms) / max(1, len(query_terms))

            heading_terms = set(tokenize(chunk.heading))
            heading_match = len(query_terms & heading_terms) / max(1, len(query_terms))

            recency = self._recency(meta, newest, oldest)
            authority = config.source_authority.get(str(meta.get("source", "")), 0.5)
            category = str(meta.get("category", ""))
            cat_prio = config.category_priority.get(category, 0.5)

            final = (config.cosine_weight * cosine
                     + config.overlap_weight * overlap
                     + config.heading_weight * heading_match
                     + config.recency_weight * recency
                     + config.authority_weight * authority
                     + config.category_weight * cat_prio)

            results.append(RankedChunk(
                chunk=chunk, cosine=cosine, term_overlap=overlap,
                heading_match=heading_match, recency=recency,
                authority=authority, category_priority=cat_prio,
                final_score=final,
            ))

        results.sort(key=lambda r: r.final_score, reverse=True)
        for i, r in enumerate(results, start=1):
            r.rank = i
        return results


# ---------------------------------------------------------------------------
# 7. Grounded answer generation
# ---------------------------------------------------------------------------

class Generator:
    """Extractive, grounded generator with [n] source citations.

    Swap this class for an LLM-backed generator in production; the retrieval
    contract (a list of RankedChunk) stays the same.
    """

    MIN_RELEVANT_COSINE = 0.10  # below this, answer "not enough information"

    @staticmethod
    def _best_sentences(chunk: Chunk, query_terms: set, max_sentences: int = 2) -> List[str]:
        scored = []
        for s in sentence_split(chunk.text):
            tokens = set(tokenize(s))
            overlap = len(tokens & query_terms)
            scored.append((overlap, len(tokens), s))
        scored.sort(key=lambda x: (-x[0], x[1]))
        relevant = [s for ov, _, s in scored if ov > 0][:max_sentences]
        if not relevant and scored:
            relevant = [scored[0][2]]
        return relevant

    def generate(self, question: str, ranked: List[RankedChunk]) -> str:
        if not ranked or ranked[0].cosine < self.MIN_RELEVANT_COSINE:
            return ("I do not have enough information in the indexed corpus to answer "
                    "this question confidently. Consider relaxing the metadata filter.")

        query_terms = set(tokenize(question))
        lines: List[str] = ["Based on the retrieved documents:"]
        used = 0
        for r in ranked[:3]:
            for sentence in self._best_sentences(r.chunk, query_terms):
                lines.append(f"- {sentence} [{r.rank}]")
                used += 1
                if used >= 4:
                    break
            if used >= 4:
                break

        lines.append("")
        lines.append("Sources:")
        for r in ranked[:3]:
            m = r.chunk.metadata
            src = ", ".join(f"{k}={v}" for k, v in m.items()
                            if k in ("source", "category", "date", "version"))
            lines.append(f"  [{r.rank}] {r.chunk.heading or r.chunk.chunk_id} ({src})")
        return "\n".join(lines)


# ---------------------------------------------------------------------------
# 8. RAG system facade
# ---------------------------------------------------------------------------

class RAGSystem:
    """Indexes documents, filters by metadata, ranks by relevance + metadata."""

    def __init__(self, ranking_config: Optional[RankingConfig] = None,
                 chunk_size: int = 400, overlap: int = 100, top_k: int = 5):
        self.chunk_size = chunk_size
        self.overlap = overlap
        self.top_k = top_k
        self.config = ranking_config or RankingConfig()
        self.ranker = Ranker(self.config)
        self.generator = Generator()
        self.vectorizer = TfidfVectorizer()
        self.chunks: List[Chunk] = []
        self.vectors: List[Dict[str, float]] = []
        self._vec_by_id: Dict[str, Dict[str, float]] = {}
        self._doc_counter = 0

    def add_documents(self, documents: Iterable[Document]) -> int:
        for doc in documents:
            chunks = chunk_document(self._doc_counter, doc, self.chunk_size, self.overlap)
            self._doc_counter += 1
            self.chunks.extend(chunks)
        self.vectorizer.fit(c.text for c in self.chunks)
        self.vectors = [self.vectorizer.transform(c.text) for c in self.chunks]
        self._vec_by_id = {c.chunk_id: v for c, v in zip(self.chunks, self.vectors)}
        return len(self.chunks)

    def _candidates_and_cosines(self, question: str,
                                filters: Optional[Dict[str, Any]]
                                ) -> Tuple[List[Chunk], List[float]]:
        candidates = MetadataFilterEngine.filter_chunks(self.chunks, filters)
        query_vec = self.vectorizer.transform(question)
        cosines = [self.vectorizer.cosine(query_vec, self._vec_by_id[c.chunk_id])
                   for c in candidates]
        return candidates, cosines

    def query(self, question: str, filters: Optional[Dict[str, Any]] = None,
              top_k: Optional[int] = None) -> QueryResult:
        k = top_k or self.top_k
        candidates, cosines = self._candidates_and_cosines(question, filters)
        ranked_all = self.ranker.rank(question, candidates, cosines)
        ranked = ranked_all[:k]
        answer = self.generator.generate(question, ranked)
        return QueryResult(
            question=question,
            answer=answer,
            ranked=ranked,
            total_chunks=len(self.chunks),
            after_filter=len(candidates),
            filter_description=MetadataFilterEngine.describe(filters),
        )

    def cosine_ranking(self, question: str, filters: Optional[Dict[str, Any]] = None,
                       top_k: int = 5) -> List[Tuple[str, str, str, str, float]]:
        """Pure relevance ordering, for comparison against metadata-boosted ranking."""
        candidates, cosines = self._candidates_and_cosines(question, filters)
        order = sorted(zip(candidates, cosines), key=lambda x: x[1], reverse=True)[:top_k]
        return [(c.chunk_id, c.heading, str(c.metadata.get("category", "")),
                 str(c.metadata.get("date", "")), s) for c, s in order]


