def make_ranking_config() -> RankingConfig:
    """Metadata signals used for ranking: source authority, category priority."""
    return RankingConfig(
        source_authority={
            "legal": 0.9, "product-docs": 0.85, "it-security": 0.85,
            "finance-reports": 0.75, "corporate-handbook": 0.70,
            "marketing": 0.50,
        },
        category_priority={"finance": 0.6, "security": 0.6, "product": 0.55},
