# ---------------------------------------------------------------------------
# 10. Evaluation
# ---------------------------------------------------------------------------

def run_evaluation(system: RAGSystem) -> bool:
    print("\n[4] Evaluation")
    checks: List[Tuple[str, bool, str]] = []

    def check(name: str, fn) -> None:
        try:
            fn()
            checks.append((name, True, ""))
        except AssertionError as exc:
            checks.append((name, False, str(exc)))

    def t_category_filter():
        res = system.query("What is the reimbursement limit for travel expenses?",
                           {"category": "finance"}, top_k=3)
        assert res.after_filter > 0, "expected finance chunks to exist"
        assert all(r.chunk.metadata.get("category") == "finance" for r in res.ranked)
        assert "Expense" in res.ranked[0].chunk.heading

    def t_tag_filter():
        res = system.query("How do I reset my password?",
                           {"tags": {"operator": "contains", "value": "password"}}, top_k=2)
        assert res.after_filter > 0
        assert all("password" in r.chunk.metadata.get("tags", []) for r in res.ranked)

    def t_date_filter():
        res = system.query("What features does the platform provide?",
                           {"date": {"operator": "gte", "value": "2024-10-15"}}, top_k=5)
        assert res.after_filter > 0
        for r in res.ranked:
            assert datetime.strptime(str(r.chunk.metadata["date"]), "%Y-%m-%d") >= \
                   datetime(2024, 10, 15)

    def t_security_ranking():
        res = system.query("How do I reset my password when locked out?",
                           {"category": "security"}, top_k=3)
        assert res.ranked[0].chunk.metadata.get("source") == "it-security"
        assert "reset" in res.answer.lower()

    def t_cross_category_no_filter():
        res = system.query("What new features were announced in the Atlas 2.0 launch?",
                           top_k=5)
        cats = {r.chunk.metadata.get("category") for r in res.ranked[:3]}
        assert cats & {"marketing", "product"}, f"got categories {cats}"

    def t_low_relevance_fallback():
        res = system.query("What is the expense reimbursement limit?",
                           {"category": "security"}, top_k=3)
        assert "do not have enough information" in res.answer.lower()

    def t_citations_present():
        res = system.query("How do I reset my password?", {"category": "security"})
        assert "Sources:" in res.answer and "[" in res.answer and "]" in res.answer

    def t_metadata_signal_in_ranking():
        res = system.query("Atlas dashboard analytics automation", top_k=5)
        assert any(r.recency > 0.8 for r in res.ranked[:3]), "recency boost not applied"
        scores = [r.final_score for r in res.ranked]
        assert scores == sorted(scores, reverse=True), "ranking not monotonic"

    for name, fn in [
        ("category filter returns only finance chunks", t_category_filter),
        ("tag 'contains' filter narrows to password docs", t_tag_filter),
        ("date >= 2024-10-15 filter excludes older chunks", t_date_filter),
        ("security query ranks IT policy first + grounded answer", t_security_ranking),
        ("no-filter query surfaces cross-category results", t_cross_category_no_filter),
        ("low-relevance + wrong filter triggers fallback answer", t_low_relevance_fallback),
        ("generated answer carries [n] citations + Sources", t_citations_present),
        ("metadata recency signal affects final ranking", t_metadata_signal_in_ranking),
    ]:
        check(name, fn)

    all_ok = True
    for name, ok, err in checks:
        all_ok &= ok
        print(f"  [{'PASS' if ok else 'FAIL'}] {name}" + (f"  -> {err}" if err else ""))
    print(f"\n  Evaluation result: {'ALL CHECKS PASSED' if all_ok else 'SOME CHECKS FAILED'}")
    return all_ok


# ---------------------------------------------------------------------------
# 11. Demo
# ---------------------------------------------------------------------------

def _print_ranked(result: QueryResult, rows: int = 3) -> None:
    print(f"  Question : {result.question}")
    print(f"  Filter   : {result.filter_description}")
    print(f"  Candidates after metadata filter: {result.after_filter} of "
          f"{result.total_chunks} chunks")
    print("  Ranked top results:")
    print("    # | chunk id          | category   | date       | cosine | final | heading")
    print("    --+-------------------+------------+------------+--------+-------+--------")
    for r in result.ranked[:rows]:
        m = r.chunk.metadata
        print(f"    {r.rank:2d} | {r.chunk.chunk_id:17s} | {str(m.get('category','')):10s} | "
              f"{str(m.get('date','')):10s} | {r.cosine:6.3f} | {r.final_score:5.3f} | "
              f"{r.chunk.heading[:38]}")
    print("\n  Answer:")
    for line in result.answer.splitlines():
        print(f"    {line}")
    print()


def _print_cosine_vs_metadata(system: RAGSystem, question: str) -> None:
    pure = system.cosine_ranking(question, top_k=5)
    blended = system.query(question, top_k=5)
    print("  Cosine-only order vs metadata-blended order:")
    print("    rank | cosine-only (chunk / score)              | metadata-blended (chunk / final)")
    print("    -----+------------------------------------------+---------------------------------")
    for i in range(max(len(pure), len(blended.ranked))):
        p = pure[i] if i < len(pure) else None
        b = blended.ranked[i] if i < len(blended.ranked) else None
        p_str = f"{p[0]} / {p[4]:.3f}" if p else "-"
        b_str = f"{b.chunk.chunk_id} / {b.final_score:.3f}" if b else "-"
        print(f"    {i+1:4d} | {p_str:40s} | {b_str}")


def run_single_query(argv: List[str]) -> None:
    def arg_value(flag: str) -> Optional[str]:
        return argv[argv.index(flag) + 1] if flag in argv else None

    question = arg_value("--query")
    if not question:
        print("Usage: --query '...' [--filters '<json>'] [--top-k N]")
        sys.exit(2)
    filters = json.loads(arg_value("--filters") or "{}")
    top_k = int(arg_value("--top-k") or "5")
    system = RAGSystem(ranking_config=make_ranking_config())
    n = system.add_documents(build_corpus())
    print(f"Indexed {n} chunks.\n")
    result = system.query(question, filters or None, top_k)
    _print_ranked(result)


def main() -> None:
    print("=" * 72)
    print(" METADATA-ENHANCED RAG SYSTEM - DEMO")
    print("=" * 72)

    system = RAGSystem(ranking_config=make_ranking_config())
    n = system.add_documents(build_corpus())
    print(f"\n[1] Index build")
    print(f"  Documents indexed : 8")
    print(f"  Chunks created    : {n}")
    print(f"  Vocabulary size   : {len(system.vectorizer.idf)}")
    print(f"  Ranking weights   : {system.config}")

    print(f"\n[2] Demo queries")
    print("-" * 72)

    print("  QUERY A - metadata filter by category (eq)")
    _print_ranked(system.query(
        "What is the reimbursement limit for travel expenses?",
        {"category": "finance"}, top_k=3))

    print("  QUERY B - metadata filter by category (eq) on a security question")
    _print_ranked(system.query(
        "How do I reset my password when locked out?",
        {"category": "security"}, top_k=3))

    print("  QUERY C - no filter: cross-category relevance ranking")
    _print_ranked(system.query(
        "What new features were announced in the Atlas 2.0 launch?", top_k=5))

    print("  QUERY D - metadata filter by date range (gte) + tag filter")
    _print_ranked(system.query(
        "What analytics and automation features does the platform provide?",
        {"date": {"operator": "gte", "value": "2024-10-15"},
         "tags": {"operator": "contains", "value": "features"}}, top_k=4))

    print("  QUERY E - negative test: wrong filter + unrelated content -> fallback")
    _print_ranked(system.query(
        "What is the expense reimbursement limit?", {"category": "hr"}, top_k=3))

    print(f"\n[3] Ranking: relevance vs metadata-enhanced")
    print("-" * 72)
    _print_cosine_vs_metadata(system, "Atlas dashboard analytics automation")

    ok = run_evaluation(system)
    print("\n" + "=" * 72)
    print(" DEMO COMPLETE" if ok else " DEMO COMPLETE (WITH FAILURES)")
    print("=" * 72)
    sys.exit(0 if ok else 1)


if __name__ == "__main__":
    if "--query" in sys.argv:
        run_single_query(sys.argv)
    else:
        main()

